corrected_code:
const { patch, param, requestBody, HttpErrors } = require('@loopback/rest');
const { repository } = require('@loopback/repository');
const { authenticate } = require('@loopback/authentication');
const { inject } = require('@loopback/core');
const { SecurityBindings } = require('@loopback/security');

class TeamManagementController {
  constructor(
    @repository('TenantMemberRepository') private memberRepo,
    @inject(SecurityBindings.USER) private caller
  ) {}

  @patch('/tenants/{tenantId}/members/{memberId}')
  @authenticate('jwt')
  async updateMemberRole(
    @param.path.string('tenantId') tenantId: string,
    @param.path.string('memberId') memberId: string,
    @requestBody() body: { role: string }
  ) {
    // Verify caller has administrator rights in the target tenant
    const callerRecord = await this.memberRepo.findOne({
      where: { tenantId, userId: this.caller.id, role: 'ADMIN' }
    });

    if (!callerRecord) {
      throw new HttpErrors.Forbidden('Caller is not an administrator of this tenant');
    }

    // Ensure member exists within the specified tenant
    const member = await this.memberRepo.findOne({
      where: { id: memberId, tenantId }
    });

    if (!member) {
      throw new HttpErrors.NotFound('Team member not found in target tenant');
    }

    await this.memberRepo.updateById(memberId, { role: body.role });
    return { success: true, memberId, updatedRole: body.role };
  }
}
